source=list(csv.DictReader(open('A1/in/part-5.tsv'),delimiter='\t'))
expected={r['id'] for r in source if r['kind'] not in {'stored','stored-directory-skeleton','account'}}
assert set(D)==expected,(expected-set(D),set(D)-expected)
p=Path('A1/c1/part-5.tsv')
seen={r['id'] for r in csv.DictReader(p.open(),delimiter='\t')}
with p.open('a') as f:
 w=csv.writer(f,delimiter='\t',lineterminator='\n')
 for r in source:
  if r['id'] in D and r['id'] not in seen:w.writerow(D[r['id']]);f.flush()
print('Individual decisions',len(D))
